from research_helpers import *
C=ev('https://www.fatetherapeutics.com/pipeline/','Current official pipeline names five distinct clinical candidates and FT-RegMed research concepts; repeated indications and trial names do not create additional candidates.')
A=ev('https://www.fatetherapeutics.com/patients/clinical-trials/','Issuer equates FT825 with ONO-8250; different partner development code is not a separate product.')
D=ev('https://ir.fatetherapeutics.com/news-releases/news-release-details/fate-therapeutics-announces-termination-collaboration-agreement','2023 issuer explicitly discontinued FT516, FT596, FT538 and FT536 programs; unnamed Janssen candidates not invented.')
H=ev('https://fatetherapeutics.com/wp-content/uploads/2021/01/FATE-Presentation_Jan20.pdf','Historical issuer portfolio identifies FT500 and FT576 as distinct NK-cell candidates; no current activity inferred.')
P=ev('https://ir.fatetherapeutics.com/news-releases/news-release-details/fate-therapeutics-provides-update-adoptive-immunotherapy','Issuer discontinued ProHema clinical development in cord blood HCT and separately names ProTmune; ingredient FT1050 is not an alias of cell product ProHema.')
N=ev('https://ir.fatetherapeutics.com/news-releases/news-release-details/fate-therapeutics-reports-fourth-quarter-2019-financial-results','Historical issuer names FATE-NK100 and ProTmune; trial completion not treated as marketing approval.')
ps=[p('FT819','Investigational CD19-targeted CAR T-cell therapy.',C,'development'),p('FT825','Investigational HER2-targeted CAR T-cell therapy.',C,'development',aliases=['ONO-8250'],evidence=[C,A]),p('FT836','Investigational MICA/B-targeted cell therapy.',C,'development'),p('FT839','Investigational CD19/CD38-targeted cell therapy.',C,'development'),p('FT522','Investigational CD19-targeted NK-cell therapy.',C,'development'),p('FT-RegMed','Regenerative medicine program for iPSC-derived cell replacement and cell factories.',C,'research')]
ps += [p(n,'Historical engineered NK-cell immunotherapy candidate.',D,'discontinued') for n in ['FT516','FT596','FT538','FT536']]
ps += [p('FT500','Historical iPSC-derived NK-cell immunotherapy candidate.',H),p('FT576','Historical BCMA-targeted CAR NK-cell immunotherapy candidate.',H),p('ProHema','Historical programmed umbilical cord blood cell therapy.',P,'discontinued'),p('ProTmune','Historical programmed mobilized peripheral blood cell therapy.',P),p('FATE-NK100','Historical donor-derived NK-cell immunotherapy candidate.',N)]
companies=[company('Fate Therapeutics Inc',ps,[C,A,D,H,P,N],'Current six named programs and nine historical cell products reviewed. Earlier small-molecule programming reagents, preclinical legacy programs and latest FT500/FT576/ProTmune rights require further reconciliation; unnamed partner products not fabricated.')]
(out/'batch-0018.json').write_text(json.dumps({'companies':companies},indent=2))
